    make(4, "一個等比數列的前三項為 4、−12、36，公比是多少？", {"A": "−4", "B": "−3", "C": "3", "D": "9"}, "B", "−12÷4＝−3，36÷(−12)＝−3，因此公比為 −3，選 B。", "公比必須用後項除以前項，負號要隨運算保留。", ["取第二項除以第一項：−12÷4＝−3。", "取第三項除以第二項：36÷(−12)＝−3。", "兩次結果相同，確認為等比數列。", "因此公比 q＝−3。", "選 B，4×(−3)＝−12 且 −12×(−3)＝36。"], "easy"),
    make(5, "等比級數 2＋6＋18＋54 的和是多少？", {"A": "72", "B": "78", "C": "80", "D": "84"}, "C", "直接相加 2＋6＋18＋54＝80，所以選 C；也可用首項 2、公比 3、4 項公式驗算。", "項數少時直接加總並用公式交叉檢查，避免把等差公式誤用在等比級數。", ["確認四項依序為 2、6、18、54。", "先算 2＋6＝8。", "再算 8＋18＝26。", "最後算 26＋54＝80。", "選 C，使用 2(3⁴−1)/(3−1) 也得 80。"], "easy"),
    make(6, "某培養皿起初有 200 個細胞，每經過一個時段數量變成原來的 2 倍。經過 4 個時段後有多少個細胞？", {"A": "800", "B": "1200", "C": "1600", "D": "3200"}, "D", "每個時段乘以 2，經過 4 個時段為 200×2⁴＝200×16＝3200，選 D。", "把倍增次數當作指數，不要把 4 只乘一次。", ["起始數量為 200。", "每一時段的倍率為 2。", "4 個時段的總倍率是 2⁴＝16。", "計算 200×16＝3200。", "選 D，逐段得到 400、800、1600、3200。"], "medium"),
    make(7, "等比數列首項為 a、公比為 2，且第三項為 20，則 a 為何？", {"A": "4", "B": "5", "C": "10", "D": "40"}, "B", "第三項 a×2²＝4a＝20，所以 a＝5，選 B。", "先把已知項寫成通項，再解一次方程式反推首項。", ["第三項公式為 a₃＝a×2³⁻¹。", "化簡為 a₃＝4a。", "依題意列式 4a＝20。", "兩邊除以 4，得 a＝5。", "選 B，5、10、20 確實符合公比 2。"], "medium"),
